(function(root){
 const KEY='colava-privacy-v1',LANG='colava-language',TTL=180*24*60*60*1000;let memory=null;
 function read(){try{const p=JSON.parse(localStorage.getItem(KEY)||'null');if(p&&p.version===1&&p.expires>Date.now())return p;if(p){localStorage.removeItem(KEY);localStorage.removeItem(LANG);}}catch{}return memory&&memory.expires>Date.now()?memory:null;}
 function save(remember){memory={version:1,rememberLanguage:!!remember,expires:Date.now()+TTL};try{localStorage.setItem(KEY,JSON.stringify(memory));if(remember)localStorage.setItem(LANG,document.documentElement.lang==='it'?'it':'en');else localStorage.removeItem(LANG);}catch{}return memory&&memory.expires>Date.now()?memory:null;}
 function language(){if(!read()?.rememberLanguage)return 'en';try{return localStorage.getItem(LANG)==='it'?'it':'en';}catch{return 'en';}}
 function saveLanguage(l){if(read()?.rememberLanguage)try{localStorage.setItem(LANG,l);}catch{}}
 function ui(l='en'){
 const it=l==='it',p=read();return `<aside id="cookie-notice" class="cookie-notice" aria-label="${it?'Cookie e preferenze':'Cookies and preferences'}" ${p?'hidden':''}><div><strong>${it?'Solo ciò che serve.':'Just what is needed.'}</strong><p>${it?'Questa pagina non aggiunge cookie pubblicitari o di analisi. Puoi scegliere se ricordare la lingua su questo dispositivo.':'This page adds no advertising or analytics cookies. You can choose whether to remember your language on this device.'} <a href="cookies.html?lang=${l}">${it?'Informazioni cookie':'Cookie information'}</a></p></div><div class="cookie-actions"><button type="button" data-cookie-essential>${it?'Solo essenziali':'Essential only'}</button><button type="button" data-cookie-open>${it?'Preferenze':'Preferences'}</button></div></aside>
 <dialog id="cookie-dialog" aria-labelledby="cookie-title"><form method="dialog"><div class="dialog-head"><h2 id="cookie-title">${it?'Le tue preferenze':'Your preferences'}</h2><button class="dialog-close" aria-label="${it?'Chiudi':'Close'}">×</button></div><p>${it?'Nessun tracciamento pubblicitario o analytics è integrato nella pagina COLAVA.':'No advertising tracking or analytics is integrated into the COLAVA page.'}</p><div class="preference-row"><div><strong>${it?'Preferenze essenziali':'Essential preferences'}</strong><p>${it?'Memorizza questa scelta per 180 giorni.':'Stores this choice for 180 days.'}</p></div><span>${it?'Sempre attive':'Always active'}</span></div><label class="preference-row"><div><strong>${it?'Ricorda la lingua':'Remember language'}</strong><p>${it?'Facoltativo. Puoi comunque cambiare lingua senza salvarla.':'Optional. You can still switch language without saving it.'}</p></div><input id="remember-language" type="checkbox" ${p?.rememberLanguage?'checked':''}></label><p class="small-note">${it?'I servizi tecnici della piattaforma di hosting sono gestiti separatamente.':'Technical services provided by the hosting platform are managed separately.'} <a href="cookies.html?lang=${l}">${it?'Leggi i dettagli':'Read the details'}</a></p><div class="cookie-actions"><button type="button" data-cookie-essential>${it?'Solo essenziali':'Essential only'}</button><button type="button" data-cookie-save>${it?'Salva preferenze':'Save preferences'}</button></div></form></dialog>`;
 }
 function footer(l='en',mode='food'){
 const it=l==='it';return `<footer class="site-footer"><div class="footer-grid"><div class="footer-brand"><a class="wordmark" href="index.html?mode=food&lang=${l}">colava<span>•</span></a><p>${it?'Impara il processo.<br>Trova la tua forma.':'Learn the process.<br>Find your form.'}</p><span>Food first. Guides first.</span></div><div><h3>${it?'Esplora':'Explore'}</h3><a href="index.html?mode=food&lang=${l}#guida">Food Forms 01</a><a href="assets/COLAVA_Food_Forms_01_Preview_${l.toUpperCase()}.pdf">${it?'Anteprima gratuita':'Free preview'}</a><a href="index.html?mode=candles&lang=${l}">Candles <small>${it?'In arrivo':'Coming soon'}</small></a></div><div><h3>${it?'In preparazione':'Coming soon'}</h3><a href="index.html?mode=food&lang=${l}#custom">Custom Food Molds</a><a href="index.html?mode=candles&lang=${l}#custom">Custom Candle Molds</a><a href="index.html?mode=${mode}&lang=${l}#materiali">${mode==='candles'?it?'Cere per stampi':'Pillar wax':it?'Materiali e utensili':'Materials & tools'}</a><a href="index.html?mode=${mode}&lang=${l}#kits">${it?'Stampi e kit':'Molds & kits'}</a></div><div><h3>${it?'Informazioni':'Information'}</h3><a href="privacy.html?lang=${l}">Privacy</a><a href="cookies.html?lang=${l}">${it?'Cookie e preferenze':'Cookies & preferences'}</a><a href="digital.html?lang=${l}">${it?'Guida digitale e acquisti':'Digital guide & purchases'}</a><button type="button" data-cookie-open>${it?'Gestisci preferenze':'Manage preferences'}</button></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} COLAVA · Altered Venganza</span><span>Trieste, ${it?'Italia · P. IVA':'Italy · VAT'} 01433140322</span></div></footer>${ui(l)}`;
 }
 root.COLAVAPrivacy={read,save,language,saveLanguage,ui,footer};if(typeof module!=='undefined')module.exports=root.COLAVAPrivacy;
 if(typeof document!=='undefined')document.addEventListener('click',e=>{const b=e.target.closest('[data-cookie-open],[data-cookie-essential],[data-cookie-save]');if(!b)return;const d=document.getElementById('cookie-dialog');if(b.hasAttribute('data-cookie-open')){const checkbox=document.getElementById('remember-language');checkbox.checked=!!read()?.rememberLanguage;d.showModal();return;}save(b.hasAttribute('data-cookie-save')&&document.getElementById('remember-language').checked);document.getElementById('cookie-notice').hidden=true;if(d.open)d.close();});
})(globalThis);
